  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Bromfenac, a structurally related benzoyl arylacetic acid NSAID, showed 67% absolute oral bioavailability in healthy fasting subjects, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Thalidomide, a small lipophilic drug with high transferability, showed probably high oral bioavailability of 80–100% at low doses in fasting volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Phenylethylmalonamide showed at least 80% oral bioavailability in normal subjects, providing affirmative evidence that structurally diverse small molecules with high transfer scores can achieve high oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Ketanserin showed 55.5% absolute oral bioavailability in healthy subjects, supporting high F for the query despite differences in ionization class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Tranexamic acid showed 33.4% systemic bioavailability under fasting conditions, still above the 20% threshold and supportive of high F, though closer to the boundary.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental bioavailability values for high-transfer analogues are above 20%, with several structurally relevant carboxylic acid/benzoyl-containing drugs showing 50–90% oral bioavailability. No evidence supports F < 20%, so the query is predicted to have high absolute oral bioavailability.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself is present in the evidence set.",
    "Some analogues differ in ionization class or contain beta-lactam/neutral scaffolds, but their high transfer scores and consistent above-threshold results reduce this uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

